export function apiError(error: unknown) {
  const message = error instanceof Error ? error.message : "UNKNOWN";
  const messages: Record<string, [number,string]> = {
    RUN_NOT_FOUND:[404,"This conversation was not found."], SUBMISSION_CONFLICT:[409,"This submission already has different saved content."], CONVERSATION_LIMIT:[409,"This conversation is full. Your existing messages are saved."], INVALID_QUESTION:[400,"This question is no longer available."],
    UNAUTHENTICATED: [401,"Sign in to research and save your idea."], AUTH_NOT_CONFIGURED: [503,"Sign-in is being connected. You can explore the sample report."],
    DATABASE_NOT_CONFIGURED: [503,"Your library is being connected. Please try again later."], INVALID_ORIGIN: [403,"This request could not be verified."],
    BUDGET_EXHAUSTED: [429,"Research is at its hackathon spending limit. Please try later."],
    ACCOUNT_QUOTA_EXHAUSTED: [409,`Your account allows ${ACCOUNT_ALLOWANCES.full} full reports and ${ACCOUNT_ALLOWANCES.refinement} refinements.`],
    REFINEMENT_NOT_ALLOWED: [409,"This report cannot be refined again."], RECONCILIATION_REQUIRED: [409,"This run needs a provider check before it can be retried. Its progress is saved."],
    INTEGRATIONS_NOT_READY: [503,"Live research is being connected. You can explore the sample report in the meantime."],
  };
  const [status, text] = messages[message] || (message.includes("one_active") ? [409,"You already have research in progress. One report can run at a time."] : message.includes("duplicate key") ? [409,"This submission already exists. Open your saved conversation."] : [500,"We couldn’t complete that request. Your draft is still here. Please try again."]);
  return Response.json({ error: text }, { status });
}
export type ResearchProvider = "openai" | "crustdata";
function runCreditAllowance(name: "CRUSTDATA_FULL_REPORT_CREDITS" | "CRUSTDATA_REFINEMENT_CREDITS") {
  const value = Number(process.env[name] || 5);
  if (!Number.isSafeInteger(value) || value < 5 || value > 1000000)
    throw new Error("INVALID_CRUST_RUN_ALLOWANCE");
  return value;
}
// Read lazily: CLI scripts load .env.local after importing this module.
// Admission persists the allowance; changing the environment never funds existing runs.
export const CRUST_CREDITS = {
  get full() { return runCreditAllowance("CRUSTDATA_FULL_REPORT_CREDITS"); },
  get refinement() { return runCreditAllowance("CRUSTDATA_REFINEMENT_CREDITS"); },
} as const;

export function crustCreditBudget() {
  const value = Number(process.env.CRUSTDATA_CREDIT_BUDGET || 0);
  if (!Number.isSafeInteger(value) || value < 0 || value > 1000000) throw new Error("INVALID_CRUST_BUDGET");
  return value;
}

export function researchProvider(): ResearchProvider {
  const value = process.env.RESEARCH_PROVIDER || "auto";
  if (value === "openai" || value === "crustdata") return value;
  if (value !== "auto") throw new Error("UNSUPPORTED_RESEARCH_PROVIDER");
  return process.env.CRUSTDATA_API_KEY && process.env.LITELLM_API_KEY && crustCreditBudget() >= CRUST_CREDITS.full ? "crustdata" : "openai";
}

export function providerReady(provider = researchProvider()) {
  return provider === "crustdata"
    ? Boolean(process.env.CRUSTDATA_API_KEY && process.env.LITELLM_API_KEY && crustCreditBudget() >= CRUST_CREDITS.full)
    : Boolean(process.env.OPENAI_API_KEY);
}

