// These account reads are free. Refuse paid requests if rates/access differ from the verified contract.
export async function checkCrustAccount(requiredCredits: number) {
  const balance = await request("/account/credits");
  const account = z
    .object({
      account: z.object({ credits: z.number().finite().nonnegative() }),
    })
    .parse(JSON.parse(balance.body));
  if (account.account.credits < requiredCredits)
    throw new Error("CRUST_BALANCE_LOW");
  for (const path of ["/web/search/live", "/web/enrich/live"]) {
    const info = await request(
      `/account/endpoints?path=${encodeURIComponent(path)}`
    );
    const endpoints = z
      .object({
        token_limit_rpm: z.number().nullable().optional(),
        endpoints: z.array(
          z.object({
            path: z.string(),
            status: z.string(),
            base_credits: z.number(),
            effective_rate_limit_rpm: z.number().nullable(),
          })
        ),
      })
      .parse(JSON.parse(info.body));
    const endpoint = endpoints.endpoints.find((e) => e.path === path);
    if (
      !endpoint ||
      endpoint.status !== "enabled" ||
      endpoint.base_credits !== 1
    )
      throw new Error("CRUST_ACCESS_OR_RATE_UNVERIFIED");
    if (
      (endpoint.effective_rate_limit_rpm !== null &&
        endpoint.effective_rate_limit_rpm < 10) ||
      (endpoints.token_limit_rpm != null && endpoints.token_limit_rpm < 10)
    )
      throw new Error("CRUST_RATE_LIMIT_UNVERIFIED");
  }
  return { credits: account.account.credits, ratesVerified: true };
}

