export const agentFunction = inngest.createFunction(
  {
    id: "continuous-agent",
    triggers: { event: "hunchlane/agent.wake" },
    concurrency: [{ limit: 2 }, { limit: 1, key: "event.data.ownerId" }],
    retries: 3,
  },
  async ({ event, step }) => {
    const { runId, ownerId } = event.data;
    if (
      typeof ownerId !== "string" ||
      !ownerId.trim() ||
      typeof runId !== "string"
    )
      throw new NonRetriableError("Invalid run identity");
    const wake = await step.run("advance", () => advanceAgent(runId, ownerId));
    if (!wake) return { finished: true };
    await step.sleepUntil("next-attempt", wake.availableAt);
    await step.sendEvent("dispatch", {
      id: wake.id,
      name: "hunchlane/agent.wake",
      data: { runId, ownerId },
    });
    await step.run("acknowledge", () => acknowledgeWake(wake));
    return { scheduled: true };
  }
);
export const agentRecoveryFunction = inngest.createFunction(
  {
    id: "continuous-agent-recovery",
    triggers: { cron: "* * * * *" },
    concurrency: { limit: 1 },
    retries: 3,
  },
  async ({ step }) => {
    if (!process.env.DATABASE_URL) return { dispatched: 0 };
    if (!(await step.run("schema-ready", agentSchemaReady)))
      return { dispatched: 0 };
    const pointers = await step.run("stalled-identities", stalledAgentPointers);
