      await step.sendEvent(`dispatch-${wake.id}`, {
        id: wake.id,
        name: "hunchlane/agent.wake",
        data: { runId: wake.runId, ownerId: wake.ownerId },
      });
      await step.run(`ack-${wake.id}`, () => acknowledgeWake(wake));
    }
